268: export function capabilityInputFingerprint(snapshot: GraphSnapshotV1): Sha256 {
269:   assertSnapshotContract(snapshot);
270:   // Content identity for the cache: the snapshot without embedded capabilities
271:   // (and without its digest, which would otherwise cover them).
272:   const stripped: Record<string, unknown> = { ...(snapshot as unknown as Record<string, unknown>) };
273:   delete stripped.capabilities;
274:   delete stripped.normalizedFingerprint;
275:   return hash(canonical(stripped));
276: }
277: export function capabilityCacheKey(snapshot: GraphSnapshotV1, config: CapabilityConfig): CapabilityCacheKey {
278:   assertCapabilityConfig(config);
279:   const inputFingerprint = capabilityInputFingerprint(snapshot);
280:   return {
281:     moduleSha256: snapshot.binaryArtifacts[0]!.contentSha256,
282:     moduleSha256s: snapshot.binaryArtifacts.map(a => a.contentSha256).sort(compareText),
283:     inputFingerprint,
284:     rulesetVersion: `${CAPABILITY_RULESET_VERSION}:${RULES_DIGEST}`,
285:     configFingerprint: fingerprint(config),
286:   };
287: }
