290: export interface CapabilityCacheStats { size: number; hits: number; misses: number }
291: /** In-memory cache keyed by binary + normalized content + ruleset version + config. */
292: export class CapabilityCache {
293:   private entries = new Map<string, { facts: CapabilityFactV1[]; modules: Sha256[] }>();
294:   private hits = 0;
295:   private misses = 0;
296:   constructor(private readonly maxEntries = 16) {
297:     if (!Number.isSafeInteger(maxEntries) || maxEntries < 1) throw new Error("capabilities: positive cache bound required");
298:   }
299:   get(key: CapabilityCacheKey): CapabilityFactV1[] | undefined {
300:     const entry = this.entries.get(keyText(key));
301:     if (entry === undefined) { this.misses += 1; return undefined; }
302:     this.hits += 1;
303:     return structuredClone(entry.facts);
304:   }
305:   set(key: CapabilityCacheKey, facts: CapabilityFactV1[]): void {
306:     if (!this.entries.has(keyText(key)) && this.entries.size >= this.maxEntries) this.entries.delete(this.entries.keys().next().value!);
307:     this.entries.set(keyText(key), { facts: structuredClone(facts), modules: [...key.moduleSha256s] });
308:   }
309:   /** Explicit invalidation: all entries, or one module's entries. Returns evicted count. */
310:   invalidate(moduleSha256?: Sha256): number {
311:     if (moduleSha256 === undefined) {
312:       const count = this.entries.size;
313:       this.entries.clear();
314:       return count;
315:     }
316:     let evicted = 0;
317:     for (const [key, value] of this.entries) if (value.modules.includes(moduleSha256)) { this.entries.delete(key); evicted += 1; }
318:     return evicted;
319:   }
