43:   if (typeof value === "number" && schema.minimum !== undefined && value < schema.minimum) errors.push(`${path}: minimum`);
44:   if (actual === "array") {
45:     if (schema.minItems !== undefined && value.length < schema.minItems) errors.push(`${path}: minItems`);
46:     if (schema.maxItems !== undefined && value.length > schema.maxItems) errors.push(`${path}: maxItems`);
47:     value.forEach((v: unknown, i: number) => schemaErrors(v, schema.items, `${path}[${i}]`, errors));
48:   }
49:   if (actual === "object") {
50:     for (const key of schema.required ?? []) if (!Object.hasOwn(value, key)) errors.push(`${path}.${key}: required`);
51:     for (const [key, v] of Object.entries(value)) {
52:       if (schema.properties?.[key]) schemaErrors(v, schema.properties[key], `${path}.${key}`, errors);
53:       else if (schema.additionalProperties === false) errors.push(`${path}.${key}: unexpected`);
54:     }
55:   }
56:   return errors;
