531: export function functionRelationKey(edge: Pick<FunctionEdgeV1, "sourceId" | "destinationId" | "kind">): string {
532:   return `relation:${hash(canonical({ sourceId: edge.sourceId, destinationId: edge.destinationId, kind: edge.kind }))}`;
