534: /** Derived view, not a v1 transport edge: its union of sites may exceed 64. */
535: export interface FunctionRelationProjection extends Omit<FunctionEdgeV1, "id"> {
536:   id: string;
537:   relationKey: string;
538:   edgeRecordIds: string[];
539: }
540: export function projectFunctionRelations(snapshot: GraphSnapshotV1): FunctionRelationProjection[] {
541:   assertSnapshotContract(snapshot);
542:   const relations = new Map<string, FunctionRelationProjection>();
543:   for (const edge of snapshot.edges) {
544:     const relationKey = functionRelationKey(edge);
545:     const previous = relations.get(relationKey);
546:     if (!previous) { relations.set(relationKey, { ...structuredClone(edge), id: relationKey, relationKey, edgeRecordIds: [edge.id] }); continue; }
547:     for (const field of ["schemaVersion", "direction", "status", "confidence", "appearedInRevision", "retiredInRevision", "schedulerRelevance"] as const) if (previous[field] !== edge[field]) throw new Error(`graph: conflicting relation shard metadata ${relationKey}`);
548:     previous.sites.push(...structuredClone(edge.sites));
549:     previous.edgeRecordIds.push(edge.id);
550:   }
551:   for (const relation of relations.values()) {
552:     relation.edgeRecordIds.sort(compareText);
553:     relation.sites = [...new Map(relation.sites.map(site => [canonical(site), site])).values()].sort((a, b) => compareAddrValues(a.siteRva, b.siteRva) || compareText(canonical(a), canonical(b)));
554:   }
555:   return [...relations.values()].sort(compareEdges);
556: }
